private final ConcurrentMap<String, CompletableFuture<Value>> inflight = new ConcurrentHashMap<>();

CompletableFuture<Value> load(String key) {
    CompletableFuture<Value> created = new CompletableFuture<>();
    CompletableFuture<Value> f = inflight.putIfAbsent(key, created);  // atomic register
    if (f != null) return f;                           // join the existing flight
    executor.execute(() -> {
        try { created.complete(source.read(key)); }    // leader runs once
        catch (Throwable t) { created.completeExceptionally(t); }
        finally { inflight.remove(key, created); }     // forget on completion
    });
    return created;
}
